const FAV_SIZES = [{size: 16, filename: "favicon-16x16.png", label: "16×16"},{size: 32, filename: "favicon-32x32.png", label: "32×32"},{size: 48, filename: "favicon-48x48.png", label: "48×48"},{size: 180, filename: "apple-touch-icon.png", label: "180×180 (apple-touch-icon)"},{size: 192, filename: "icon-192.png", label: "192×192 (manifest)"},{size: 512, filename: "icon-512.png", label: "512×512 (manifest)"}, ];const FAV_PREVIEW_SIZE = 320;let favImg = null;let favDrawW = 0, favDrawH = 0, favOffsetX = 0, favOffsetY = 0;let favDragging = false, favDragStartX = 0, favDragStartY = 0, favDragOrigX = 0, favDragOrigY = 0;function favBaseScale(){return Math.max(FAV_PREVIEW_SIZE / favImg.naturalWidth, FAV_PREVIEW_SIZE / favImg.naturalHeight);}function favResetCrop(){const zoom = parseInt(document.getElementById("fav-zoom").value, 10) / 100;const scale = favBaseScale() * zoom;favDrawW = favImg.naturalWidth * scale;favDrawH = favImg.naturalHeight * scale;favOffsetX = (FAV_PREVIEW_SIZE - favDrawW) / 2;favOffsetY = (FAV_PREVIEW_SIZE - favDrawH) / 2;}function favClampOffset(){const minX = FAV_PREVIEW_SIZE - favDrawW, minY = FAV_PREVIEW_SIZE - favDrawH;favOffsetX = Math.min(0, Math.max(minX, favOffsetX));favOffsetY = Math.min(0, Math.max(minY, favOffsetY));}function favRedraw(){const canvas = document.getElementById("fav-crop-canvas");const ctx = canvas.getContext("2d");ctx.clearRect(0, 0, FAV_PREVIEW_SIZE, FAV_PREVIEW_SIZE);ctx.drawImage(favImg, favOffsetX, favOffsetY, favDrawW, favDrawH);}function favRecomputeZoom(){const zoom = parseInt(document.getElementById("fav-zoom").value, 10) / 100;const scale = favBaseScale() * zoom;const centerX = favOffsetX + favDrawW / 2, centerY = favOffsetY + favDrawH / 2;favDrawW = favImg.naturalWidth * scale;favDrawH = favImg.naturalHeight * scale;favOffsetX = centerX - favDrawW / 2;favOffsetY = centerY - favDrawH / 2;favClampOffset();favRedraw();}function favLoadFile(file){if (!file || !file.type.startsWith("image/")) return;document.getElementById("fav-filename").textContent = `> loaded: ${file.name}`;const reader = new FileReader();reader.onload = (e) =>{const img = new Image();img.onload = () =>{favImg = img;document.getElementById("fav-crop-wrap").style.display = "";document.getElementById("fav-output").style.display = "none";document.getElementById("fav-zoom").value = 100;favResetCrop();favRedraw();GAMA.say("success");};img.src = e.target.result;};reader.readAsDataURL(file);} function favRenderSize(size){const sf = size / FAV_PREVIEW_SIZE;const canvas = document.createElement("canvas");canvas.width = size;canvas.height = size;const ctx = canvas.getContext("2d");ctx.drawImage(favImg, favOffsetX * sf, favOffsetY * sf, favDrawW * sf, favDrawH * sf);return new Promise((resolve) => canvas.toBlob(resolve, "image/png"));}async function favGenerate(){const grid = document.getElementById("fav-preview-grid");grid.innerHTML = "";for (const spec of FAV_SIZES){const blob = await favRenderSize(spec.size);const url = URL.createObjectURL(blob);const cell = document.createElement("div");cell.className = "fav-preview-cell";cell.innerHTML = `
      <img src="${url}" alt="${spec.label}" width="48" height="48">
      <p>${spec.label}</p>
      <a href="${url}" download="${spec.filename}" class="btn">&gt; ${spec.filename}</a>
    `;grid.appendChild(cell);}const headLines = [ '<link rel="icon" type="image/png" sizes="16x16" href="/favicon-16x16.png">', '<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png">', '<link rel="icon" type="image/png" sizes="48x48" href="/favicon-48x48.png">', '<link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png">', '<link rel="manifest" href="/site.webmanifest">', ];document.getElementById("fav-head-snippet").textContent = headLines.join("\n");const manifest ={icons: [{src: "/icon-192.png", sizes: "192x192", type: "image/png"},{src: "/icon-512.png", sizes: "512x512", type: "image/png"}, ],};document.getElementById("fav-manifest-snippet").textContent = JSON.stringify(manifest, null, 2);document.getElementById("fav-output").style.display = "";GAMA.log("Favicon set generated - 6 sizes, PNG only.");GAMA.say("success");}function initFaviconGenerator(){const dropzone = document.getElementById("fav-dropzone");const input = document.getElementById("fav-file-input");dropzone.addEventListener("click", () => input.click());["dragover", "dragleave", "drop"].forEach((evt) => dropzone.addEventListener(evt, (e) =>{e.preventDefault();dropzone.classList.toggle("dragover", evt === "dragover");if (evt === "drop") favLoadFile(e.dataTransfer.files[0]);}) );input.addEventListener("change", () => favLoadFile(input.files[0]));const canvas = document.getElementById("fav-crop-canvas");canvas.addEventListener("mousedown", (e) =>{favDragging = true;favDragStartX = e.clientX;favDragStartY = e.clientY;favDragOrigX = favOffsetX;favDragOrigY = favOffsetY;canvas.style.cursor = "grabbing";});window.addEventListener("mousemove", (e) =>{if (!favDragging) return;const scale = canvas.width / canvas.getBoundingClientRect().width;favOffsetX = favDragOrigX + (e.clientX - favDragStartX) * scale;favOffsetY = favDragOrigY + (e.clientY - favDragStartY) * scale;favClampOffset();favRedraw();});window.addEventListener("mouseup", () =>{favDragging = false;canvas.style.cursor = "grab";});document.getElementById("fav-zoom").addEventListener("input", favRecomputeZoom);document.getElementById("fav-generate-btn").addEventListener("click", favGenerate);document.getElementById("fav-copy-head").addEventListener("click", () =>{navigator.clipboard.writeText(document.getElementById("fav-head-snippet").textContent);GAMA.log("Copied <head> snippet");GAMA.say("success");});document.getElementById("fav-copy-manifest").addEventListener("click", () =>{navigator.clipboard.writeText(document.getElementById("fav-manifest-snippet").textContent);GAMA.log("Copied site.webmanifest snippet");GAMA.say("success");});}document.addEventListener("DOMContentLoaded", initFaviconGenerator);